     1	export type ContentfulAsset = {
     2	  sys: {
     3	    id: string;
     4	  };
     5	  fields: {
     6	    title: string;
     7	    description?: string;
     8	    file: {
     9	      url: string;
    10	      fileName: string;
    11	      contentType: string;
    12	      details: {
    13	        size: number;
    14	        image?: {
    15	          width: number;
    16	          height: number;
    17	        };
    18	      };
    19	    };
    20	  };
    21	};
    22	
    23	export type ContentfulRichText = {
    24	  nodeType: string;
    25	  data: Record<string, unknown>;
    26	  content: ContentfulRichTextNode[];
    27	};
    28	
    29	export type ContentfulRichTextNode = {
    30	  nodeType: string;
    31	  value?: string;
    32	  data?: Record<string, unknown>;
    33	  content?: ContentfulRichTextNode[];
    34	  marks?: Array<{
    35	    type: string;
    36	  }>;
    37	};
    38	
    39	export type HomepageEntry = {
    40	  sys: {
    41	    id: string;
    42	    contentType: {
    43	      sys: {
    44	        id: 'homepage';
    45	      };
    46	    };
    47	  };
    48	  fields: {
    49	    heroBanner?: ContentfulAsset;
    50	    duplexSection?: ContentfulRichText;
    51	    videoEmbed?: ContentfulAsset;
    52	    productHero?: string;
    53	  };
    54	};
    55	
    56	// ---------------------------------------------------------------------------
    57	// Region content type
    58	// Canonical, referenceable region/storefront entity — any content type needing
    59	// region-scoping (link, footerConfig, etc.) references this via a `regions` field
    60	// instead of duplicating a hardcoded site-ID list. Seeded with one entry per SFCC site
    61	// by scripts/contentful/setup/seedRegions.mjs.
    62	// ---------------------------------------------------------------------------
    63	
    64	export type RegionEntry = {
    65	  sys: {
    66	    id: string;
    67	    contentType: { sys: { id: 'region' } };
    68	  };
    69	  fields: {
    70	    /** SFCC site ID (e.g. 'ZimmermannAU') — the canonical join key. */
    71	    siteId: string;
    72	    /** Editor-facing display name (e.g. 'Australia'). Admin label, not shopper-facing. */
    73	    label: string;
    74	    /** Informational only — mirrors the site's primary locale. */
    75	    locale?: string;
    76	  };
    77	};
    78	
    79	// ---------------------------------------------------------------------------
    80	// Footer content types
    81	// Live content types — see scripts/contentful/content-types/link.js, footerNavGroup.js,
    82	// footerConfig.js, authored via scripts/contentful/buildTemplate.js and installed per
    83	// environment via scripts/contentful/setup/installTemplate.mjs.
    84	// ---------------------------------------------------------------------------
    85	
    86	export type LinkEntry = {
    87	  sys: {
    88	    id: string;
    89	    contentType: { sys: { id: 'link' } };
    90	  };
    91	  fields: {
    92	    label: string;
    93	    href: string;
    94	    /**
    95	     * Regions this link applies to. Omitted/empty = applies to all regions (the
    96	     * default/global case) — see overrides/app/utils/resolveByRegion.ts.
    97	     */
    98	    regions?: ReadonlyArray<RegionEntry>;
    99	  };
   100	};
   101	
   102	export type FooterNavGroupEntry = {
   103	  sys: {
   104	    id: string;
   105	    contentType: { sys: { id: 'footerNavGroup' } };
   106	  };
   107	  fields: {
   108	    heading: string;
   109	    readonly links: ReadonlyArray<LinkEntry>;
   110	    /**
   111	     * Renders the contact-channel icon row beneath this group's links.
   112	     *
   113	     * A flag rather than matching the heading text: `heading` is a localised Contentful
   114	     * value, so `heading === 'Contact'` silently stops matching the moment an editor writes
   115	     * "Kontakt" or "Contacto" — and this footer ships to eight storefronts.
   116	     */
   117	    showContactChannels?: boolean;
   118	  };
   119	};
   120	
   121	export type FooterConfigEntry = {
   122	  sys: {
   123	    id: string;
   124	    contentType: { sys: { id: 'footerConfig' } };
   125	  };
   126	  fields: {
   127	    internalTitle: string;
   128	    subscribeHeading?: string;
   129	    subscribeBody?: string;
   130	    // Read-only both ways. The footer only ever .maps these, but footer/index.stories.content.ts's
   131	    // FOOTER_FIXTURE is a plain module singleton multiple stories in index.stories.tsx read
   132	    // directly, so an in-place push/sort/index-assign anywhere would corrupt every other
   133	    // story reading the same object. ReadonlyArray blocks push/pop/splice/sort/reverse/
   134	    // index-assign/length; the `readonly` property modifier additionally blocks swapping the
   135	    // whole array out. Matches BottomBarProps.legalLinks in footer/index.tsx, which already
   136	    // types its array as ReadonlyArray<>.
   137	    readonly navGroups: ReadonlyArray<FooterNavGroupEntry>;
   138	    readonly legalLinks?: ReadonlyArray<LinkEntry>;
   139	    copyrightOwner?: string;
   140	    phoneHref?: string;
   141	    whatsAppHref?: string;
   142	    emailHref?: string;
   143	    /**
   144	     * Regions this footer applies to. Omitted/empty = the default/global footer for its
   145	     * locale. A narrower-scoped entry takes precedence when resolving which footerConfig
   146	     * to render for a given site — see overrides/app/utils/resolveByRegion.ts.
   147	     */
   148	    readonly regions?: ReadonlyArray<RegionEntry>;
   149	  };
   150	};
   151	
   152	// ---------------------------------------------------------------------------
   153	// UI copy content type
   154	// One entry per UI string (error text, input placeholders, CTA labels, etc.) — fetched
   155	// in bulk and reduced into a key→value map. See scripts/contentful/content-types/uiCopy.js.
   156	// ---------------------------------------------------------------------------
   157	
   158	export type UiCopyEntry = {
   159	  sys: {
   160	    id: string;
   161	    contentType: { sys: { id: 'uiCopy' } };
   162	  };
   163	  fields: {
   164	    /** Editor-facing friendly name — never rendered in the app. See uiCopy.js's title field. */
   165	    title: string;
   166	    key: string;
   167	    value: string;
   168	    description?: string;
   169	  };
   170	};
   171	
   172	export type AnyContentfulEntry = {
   173	  sys: {
   174	    id: string;
   175	    contentType?: {
   176	      sys: {
   177	        id: string;
   178	      };
   179	    };
   180	  };
   181	  fields: Record<string, unknown>;
   182	};
   183	
   184	export type ContentfulResponse<T> = {
   185	  sys: {
   186	    type: string;
   187	  };
   188	  fields: T;
   189	};

