════════ overrides/app/components/footer/index.tsx ════════
     1	import React, { useEffect, useState } from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
     4	import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
     5	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
     6	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
     7	import { useHistory } from 'react-router-dom';
     8	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
     9	import { useContentfulClient } from 'app/hooks/useContentfulClient';
    10	import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
    11	import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
    12	import { FooterNavColumn } from './footerNavColumn';
    13	import { BottomBar } from './bottomBar';
    14	
    15	const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
    16	
    17	// ---------------------------------------------------------------------------
    18	// Types
    19	// ---------------------------------------------------------------------------
    20	type FooterProps = {
    21	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from index.stories.content.ts in stories/tests. */
    22	  data: FooterConfigEntry;
    23	  copyrightYear?: number;
    24	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
    25	  initialSubscribed?: boolean;
    26	  /**
    27	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
    28	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
    29	   */
    30	  enableNameCapture?: boolean;
    31	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
    32	   *  noop so the presentational Footer never navigates on its own. */
    33	  onLogoClick?: () => void;
    34	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
    35	  privacyPolicyHref?: string;
    36	};
    37	
    38	// ---------------------------------------------------------------------------
    39	// Footer
    40	// ---------------------------------------------------------------------------
    41	
    42	/**
    43	 * Zimmermann global footer — presentational. Receives its content as props and fetches
    44	 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
    45	 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
    46	 *
    47	 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
    48	 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
    49	 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
